import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator 2023-05-02","description":"","frontmatter":{"title":"Ceph Orchestrator 2023-05-02","date":"2023-05-02T00:00:00.000Z","updated":"2023-05-03T00:00:00.000Z","tags":["Ceph","分布式存储","Cephadm","管理工具","IPv6","开发","容器化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_2023-05-02.md","filePath":"posts/2023/Ceph_Orchestrator_2023-05-02.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Orchestrator_2023-05-02.md"};function o(h,a,s,d,n,p){return l(),i("div",null,[...a[0]||(a[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><ol><li>IPv6 相关问题讨论</li><li>开发基于包的 Ceph 管理工具（Cephadm）的可能性</li></ol><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ul><li><p><strong>IPv6 问题</strong>：</p><ul><li>讨论了 IPv6 地址绑定问题，特别是由于 IPv6 地址需要额外的字段（如 flow info 和 scope ID）导致的绑定失败。</li><li>提出了进一步研究如何处理这些字段，特别是 scope ID 的确定方法。</li><li>决定将此议题留待后续讨论，以便有更多时间进行深入研究。</li></ul></li><li><p><strong>基于包的 Cephadm 开发</strong>：</p><ul><li>讨论了开发一个基于包的管理工具的可能性，以满足那些不希望使用容器化 Ceph 的用户需求。</li><li>分析了现有 Cephadm 代码库的结构，指出大部分工作将集中在底层功能的实现上，如包的安装、守护进程的部署和设备检测。</li><li>提出了可能的开发路径，包括重用现有代码、创建新的管理模块，以及如何处理与现有容器化 Cephadm 的兼容性问题。</li><li>讨论了可能的技术挑战，如安全更新和调试工具的集成。</li></ul></li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>将 IPv6 绑定问题的深入讨论推迟到下一次会议。</li><li>对于基于包的 Cephadm 开发，决定由感兴趣的团队成员进行初步的概念验证工作，并计划在未来几周内进行更详细的讨论和规划。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>对 IPv6 绑定问题进行更多的研究和测试，以确定最佳的解决方案。</li><li>开发基于包的 Cephadm 的初步原型，重点关注底层功能的实现。</li><li>安排下一次会议，以讨论基于包的 Cephadm 开发的进展和遇到的任何问题。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点： <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点：&quot;">​</a></h4><ul><li>讨论了容器化 Ceph 的安全性和用户对容器技术的担忧，提出了改进容器工具和文档的建议。</li><li>提到了现有 Cephadm 代码库的 refactoring 计划，以及如何与新的开发工作协调。</li></ul><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Dan VanderSark</li><li>Kathy</li><li>其他相关开发人员</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，参会人员对未来的开发工作表示了积极的期待。</li></ul>',16)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
